void expect(const bool condition, const std::string_view message) {
    if (condition) return;
    std::cerr << "generated property test failure: " << message << '\n';
    std::exit(EXIT_FAILURE);
}

// Counts any change event's raises.
struct RaiseCounter final {
    int* count{};
    template <typename... Arguments>
    void operator()(Arguments&&...) const {
        ++(*count);
    }
};

void test_button_base_properties() {
    std::shared_ptr<Button> control = make_control<Button>(StableId("generated.buttonbase"));
    {
        const std::string sample = std::string("codemod sample");
        int raises = 0;
        const SubscriptionToken token = (*control).text_changed().subscribe(RaiseCounter{&raises});
        (*control).text = sample;
        expect((*control).text.read() == sample, "ButtonBase.text: a write stores");
        expect(raises == 1, "ButtonBase.text: a changed write raises once");
        (*control).text = sample;
        expect(raises == 1, "ButtonBase.text: an equal write raises nothing");
        static_cast<void>(token);
        const std::optional<BindingValue> by_name = (*control).property_value("text");
        expect(by_name && *by_name == PropertyValueTraits<std::string>::to_binding(sample),
               "ButtonBase.text: the table reads the cell");
    }
    {
        const ContentAlignment sample = ContentAlignment::top_left;
        (*control).text_alignment = sample;
        expect((*control).text_alignment.read() == sample, "ButtonBase.text_alignment: a write stores");
        const std::optional<BindingValue> by_name = (*control).property_value("text_alignment");
        expect(by_name && *by_name == PropertyValueTraits<ContentAlignment>::to_binding(sample),
               "ButtonBase.text_alignment: the table reads the cell");
    }
    {
        const FontSpec sample = FontSpec{FontRole::control, 14.0, 600, false, 0.24};
        (*control).font = sample;
        expect((*control).font.read() == sample, "ButtonBase.font: a write stores");
        const std::optional<BindingValue> by_name = (*control).property_value("font");
        expect(by_name && *by_name == PropertyValueTraits<FontSpec>::to_binding(sample),
               "ButtonBase.font: the table reads the cell");
    }
    {
        const Insets sample = Insets{1.0, 2.0, 3.0, 4.0};
        (*control).content_padding = sample;
        expect((*control).content_padding.read() == sample, "ButtonBase.content_padding: a write stores");
        const std::optional<BindingValue> by_name = (*control).property_value("content_padding");
        expect(by_name && *by_name == PropertyValueTraits<Insets>::to_binding(sample),
               "ButtonBase.content_padding: the table reads the cell");
    }
    {
        const double sample = 1.5;
        (*control).text_line_spacing = sample;
        expect((*control).text_line_spacing.read() == sample, "ButtonBase.text_line_spacing: a write stores");
    }
    {
        const ContentAlignment sample = ContentAlignment::bottom_right;
        (*control).image_alignment = sample;
        expect((*control).image_alignment.read() == sample, "ButtonBase.image_alignment: a write stores");
    }
    {
        const TextImageRelation sample = TextImageRelation::image_before_text;
        (*control).text_image_relation = sample;
        expect((*control).text_image_relation.read() == sample, "ButtonBase.text_image_relation: a write stores");
    }
    {
        const double sample = 8.0;
        (*control).image_gap = sample;
        expect((*control).image_gap.read() == sample, "ButtonBase.image_gap: a write stores");
    }
    {
        const bool sample = !(*control).use_mnemonic.read();
        (*control).use_mnemonic = sample;
        expect((*control).use_mnemonic.read() == sample, "ButtonBase.use_mnemonic: a write stores");
    }
    {
        const std::optional<bool> sample = std::optional<bool>{true};
        int raises = 0;
        const SubscriptionToken token = (*control).expanded_changed().subscribe(RaiseCounter{&raises});
        (*control).expanded_state = sample;
        expect((*control).expanded_state.read() == sample, "ButtonBase.expanded_state: a write stores");
        expect(raises == 1, "ButtonBase.expanded_state: a changed write raises once");
        (*control).expanded_state = sample;
        expect(raises == 1, "ButtonBase.expanded_state: an equal write raises nothing");
        static_cast<void>(token);
    }
}

